function setAnchorDestination(attributes: string, href: string, external = false) {
  let next = attributes
    .replace(/\s+href="[^"]*"/, "")
    .replace(/\s+target="[^"]*"/, "")
    .replace(/\s+rel="[^"]*"/, "");

  next = ` href="${href}"${next}`;
  if (external) next += ' target="_blank" rel="noopener noreferrer"';
  return next;
}

function setInlineStyle(attributes: string, style: string) {
  const next = attributes.replace(/\s+style="[^"]*"/, "");
  return `${next} style="${style}"`;
}

function addAttribute(attributes: string, name: string, value = "") {
  if (new RegExp(`\\s${name}(=|\\s|$)`).test(attributes)) return attributes;
  return `${attributes} ${name}${value ? `="${value}"` : ""}`;
}

function stripLegacyWhatsAppButton(html: string) {
  return html.replace(
    /\n\s*<a\b[^>]*aria-label="Chat on WhatsApp"[^>]*>[\s\S]*?<\/a>/,
    "",
  );
}

function prepareHeaderNavigation(html: string) {
  let next = html.replace(
    /\/assets\/sitesbrand-wordmark-transparent\.(?:png|webp)/,
    "/assets/sitesbrand-full-logo-white-s-transparent-final-220.avif",
  );
  next = next.replace(
    'src="/assets/sitesbrand-full-logo-white-s-transparent-final-220.avif"',
    'src="/assets/sitesbrand-full-logo-white-s-transparent-final-220.avif" decoding="async"',
  );

  const solutionsStart = next.indexOf(
    '<div style="position:relative" data-menu-container="solutions">',
  );
  const caseStudiesStart = next.indexOf('<a href="#cases"', solutionsStart);
  if (solutionsStart >= 0 && caseStudiesStart > solutionsStart) {
    next = `${next.slice(0, solutionsStart)}${next.slice(caseStudiesStart)}`;
  }

  const caseStudyMenuItems = caseStudies
    .map((study, index) => `<a href="/case-studies/${study.slug}" style="display:block;padding:11px 14px;border-radius:10px;text-decoration:none;color:var(--lmuted);font-size:14px${index === 0 ? ";font-weight:600" : ""}">${study.name}${index === 0 ? ' <span style="color:#006f7c;font-size:10px;margin-left:6px">FEATURED</span>' : ""}</a>`)
    .join("");
  const caseStudyDropdown = `<div style="position:relative" data-menu-container="case-studies">
          <button style="display:flex;align-items:center;gap:6px;background:none;border:none;color:var(--ltext);font:inherit;font-size:15px;font-weight:500;padding:9px 14px;cursor:pointer;border-radius:10px">Case Studies <span style="font-size:10px;opacity:.6">▼</span></button>
          <div data-menu-panel="case-studies" style="display:none;position:absolute;top:46px;left:0;width:285px;background:var(--lcard);border:1px solid var(--lborder);border-radius:16px;box-shadow:var(--lshadow);padding:10px">
            <a href="/case-studies" style="display:block;padding:11px 14px;border-radius:10px;text-decoration:none;color:var(--ltext);font-size:14px;font-weight:700">View all case studies</a>${caseStudyMenuItems}
          </div>
        </div>`;
  next = next.replace(/<a href="#cases"[^>]*>Case Studies<\/a>/, caseStudyDropdown);

  const desktopNavEndMarker =
    '\n      </div>\n\n      <div style="display:flex;align-items:center;gap:10px;flex:none" data-desktop-nav>';
  const desktopNavEnd = next.indexOf(desktopNavEndMarker);
  if (desktopNavEnd >= 0) {
    const contactLink =
      '\n        <a href="/contact" style="text-decoration:none;color:var(--ltext);font-size:15px;font-weight:500;padding:9px 14px;border-radius:10px">Contact</a>';
    next = `${next.slice(0, desktopNavEnd)}${contactLink}${next.slice(desktopNavEnd)}`;
  }

  const headerActionsStart = next.indexOf(
    '<div style="display:flex;align-items:center;gap:10px;flex:none" data-desktop-nav>',
  );
  const strategyCallStart = next.indexOf(
    '<a href="https://calendly.com/hassamshabbir/30min"',
    headerActionsStart,
  );
  const auditButtonStart = next.indexOf('<a href="#cta"', strategyCallStart);
  if (
    headerActionsStart >= 0
    && strategyCallStart > headerActionsStart
    && auditButtonStart > strategyCallStart
  ) {
    next = `${next.slice(0, strategyCallStart)}${next.slice(auditButtonStart)}`;
  }

  const mobileProcessLink =
    '<a href="#process" data-close-mobile style="display:block;padding:12px 4px;text-decoration:none;color:var(--ltext);font-weight:600;border-bottom:1px solid var(--lborder)">Our Process</a>\n      ';
  const mobileFaqLink =
    '<a href="#faq" data-close-mobile style="display:block;padding:12px 4px;text-decoration:none;color:var(--ltext);font-weight:600;border-bottom:1px solid var(--lborder)">FAQs</a>';
  const mobileResourcesAndContact =
    '<a href="/resources/blog" data-close-mobile style="display:block;padding:12px 4px;text-decoration:none;color:var(--ltext);font-weight:600;border-bottom:1px solid var(--lborder)">Resources</a>\n      <a href="/contact" data-close-mobile style="display:block;padding:12px 4px;text-decoration:none;color:var(--ltext);font-weight:600;border-bottom:1px solid var(--lborder)">Contact</a>';
  const mobileCaseStudyLinks = `<a href="/case-studies" data-close-mobile style="display:block;padding:12px 4px;text-decoration:none;color:var(--ltext);font-weight:700;border-bottom:1px solid var(--lborder)">Case Studies</a>
      ${caseStudies.map((study) => `<a href="/case-studies/${study.slug}" data-close-mobile style="display:block;padding:9px 4px 9px 18px;text-decoration:none;color:var(--lmuted);font-size:13px;font-weight:600;border-bottom:1px solid var(--lborder)">${study.name}</a>`).join("\n      ")}`;
  return next
    .replace(/<a href="#cases" data-close-mobile[^>]*>Case Studies<\/a>/, mobileCaseStudyLinks)
    .replace(mobileProcessLink, "")
    .replace(mobileFaqLink, mobileResourcesAndContact);
}

function wireHomepageActions(html: string) {
  return html.replace(/<a\b([^>]*)>([\s\S]*?)<\/a>/g, (anchor, attributes: string, content: string) => {
    const text = content
      .replace(/<[^>]+>/g, " ")
      .replaceAll("&amp;", "&")
      .replace(/\s+/g, " ")
      .trim();
    const ariaLabel = attributes.match(/aria-label="([^"]+)"/)?.[1];

    if (text.startsWith("Book a Strategy Call")) {
      return `<a${setAnchorDestination(addAttribute(setInlineStyle(attributes, secondaryStrategyStyle), "data-secondary-cta"), siteConfig.calendlyUrl, true)}>${content}</a>`;
    }
    if (text.startsWith("Get a Free Audit")) {
      const auditStyle = attributes.includes("data-close-mobile") ? mobilePrimaryAuditStyle : primaryAuditStyle;
      return `<a${setAnchorDestination(addAttribute(setInlineStyle(attributes, auditStyle), "data-primary-audit-cta"), auditRequestUrl)}>${content}</a>`;
    }
    if (text.startsWith("Let's Build Your Growth Engine")) {
      return `<a${setAnchorDestination(attributes, siteConfig.whatsappUrl, true)}>${content}</a>`;
    }
    if (ariaLabel === "Chat on WhatsApp") {
      return `<a${setAnchorDestination(attributes, siteConfig.whatsappUrl, true)}>${content}</a>`;
    }
    if (ariaLabel === "LinkedIn") {
      return `<a${setAnchorDestination(attributes, siteConfig.social.linkedin, true)}>${content}</a>`;
    }
    if (ariaLabel === "Facebook") {
      return `<a${setAnchorDestination(attributes, siteConfig.social.facebook, true)}>${content}</a>`;
    }
    if (ariaLabel === "X / Twitter") {
      return `<a${setAnchorDestination(attributes, "/social/x")}>${content}</a>`;
    }
    if (ariaLabel === "TikTok") {
      return `<a${setAnchorDestination(attributes, "/social/tiktok")}>${content}</a>`;
    }
    if (actionRoutes[text]) {
      return `<a${setAnchorDestination(attributes, actionRoutes[text])}>${content}</a>`;
    }
    const currentHref = attributes.match(/\shref="([^"]*)"/)?.[1];
    if (currentHref && /^#(services|process|cases|team|faq)$/.test(currentHref)) {
      return `<a${setAnchorDestination(attributes, `/${currentHref}`)}>${content}</a>`;
    }
    return anchor;
  });
}

