function renderCrawlableStats(html: string) {
  return html.replace(
    /(<[^>]*class="count"[^>]*data-count="([^"]+)"[^>]*data-suffix="([^"]*)"[^>]*>)[^<]*(<\/[^>]+>)/g,
    (_match, openingTag: string, value: string, suffix: string, closingTag: string) =>
      `${openingTag}${value}${suffix}${closingTag}`,
  );
}

